  // your code here
}

test_suite:
function mountFocus() {
  const state: { focused?: boolean } = {};
  function Target() {
    const [ref, isFocused] = useFocus<HTMLInputElement>();
    state.focused = isFocused;
    return <input ref={ref} />;
  }
  const view = render(<Target />);
  return { state, el: view.container.firstChild as HTMLInputElement, unmount: view.unmount };
}

test('isFocused is false initially', () => {
  const { result } = renderHook(() => useFocus());
  expect(result.current[1]).toBe(false);
});

test('isFocused is true after focus event', () => {
  const { state, el } = mountFocus();
  act(() => { el.dispatchEvent(new FocusEvent('focus')); });
  expect(state.focused).toBe(true);
});

test('isFocused is false after blur event', () => {
  const { state, el } = mountFocus();
  act(() => { el.dispatchEvent(new FocusEvent('focus')); });
  act(() => { el.dispatchEvent(new FocusEvent('blur')); });
  expect(state.focused).toBe(false);
});

// __hidden__
test('listener removed on unmount', () => {
  const { el, unmount } = mountFocus();
  const removeSpy = vi.spyOn(el, 'removeEventListener');
  unmount();
  expect(removeSpy).toHaveBeenCalledWith('focus', expect.any(Function));
});

solution:
import { useEffect, useRef, useState } from 'react';

export function useFocus<T extends Element>(): [React.RefObject<T>, boolean] {
  const ref = useRef<T>(null);
  const [isFocused, setIsFocused] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onFocus = () => setIsFocused(true);
    const onBlur = () => setIsFocused(false);
    el.addEventListener('focus', onFocus);
    el.addEventListener('blur', onBlur);
    return () => {
      el.removeEventListener('focus', onFocus);
      el.removeEventListener('blur', onBlur);
    };
  }, []);

  return [ref, isFocused];
}
